Una pizzería prepara los pedidos en el orden en que entran y quiere saber qué pedidos están hechos y cuáles esperan.

function cocina(sucesos) {
  const pendientes = [];
  const hechos = [];
  for (const s of sucesos) {
    if (s.tipo === "pedido") pendientes.push(s.numero);
    else if (pendientes.length > 0) hechos.push(pendientes.shift());
  }
  return { hechos, pendientes };
}
